import { useState } from 'react';
import Button from '../components/Button';

const questions = [
  {
    id: 1,
    question: 'Which SQL command is used to remove duplicates from query results?',
    options: ['DISTINCT', 'GROUP BY', 'UNION', 'FILTER'],
    answer: 'DISTINCT',
  },
  {
    id: 2,
    question: 'Which layer of the OSI model handles routing?',
    options: ['Transport', 'Network', 'Data Link', 'Session'],
    answer: 'Network',
  },
  {
    id: 3,
    question: 'Which design model is best for evolving requirements?',
    options: ['Waterfall', 'V-Model', 'Spiral', 'Agile'],
    answer: 'Agile',
  },
];

export default function QuizPage() {
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const score = questions.reduce((acc, question) => {
    return acc + (selected[question.id] === question.answer ? 1 : 0);
  }, 0);

  return (
    <div className="space-y-8">
      <div className="rounded-[2rem] border border-slate-800 bg-slate-950/90 p-8 shadow-2xl shadow-slate-950/30">
        <h2 className="text-3xl font-semibold text-white">Assessment quiz</h2>
        <p className="mt-3 text-slate-400">Test your fundamentals with a short multiple-choice quiz.</p>
        <div className="mt-8 space-y-6">
          {questions.map((question) => (
            <div key={question.id} className="space-y-4 rounded-3xl border border-slate-800 bg-slate-900/95 p-5">
              <div className="text-lg font-semibold text-white">{question.question}</div>
              <div className="grid gap-3 sm:grid-cols-2">
                {question.options.map((option) => (
                  <button
                    key={option}
                    type="button"
                    onClick={() => setSelected((prev) => ({ ...prev, [question.id]: option }))}
                    className={`rounded-3xl border px-4 py-3 text-left transition ${
                      selected[question.id] === option
                        ? 'border-cyan-500 bg-cyan-500/10 text-cyan-200'
                        : 'border-slate-800 bg-slate-950 text-slate-300 hover:border-cyan-500/30 hover:bg-slate-900'
                    }`}
                  >
                    {option}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
        <div className="mt-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <Button onClick={() => setSubmitted(true)}>Submit quiz</Button>
          {submitted && (
            <div className="rounded-3xl bg-cyan-500/10 px-4 py-3 text-sm text-cyan-200">
              Score: {score} / {questions.length}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
